def components(g, barrier=2):
 R,C=len(g),len(g[0]); seen=set(); obs=[]
 for r in range(R):
  for c in range(C):
   col=g[r][c]
   if col in (0,barrier) or (r,c) in seen: continue
   todo=[(r,c)]; seen.add((r,c)); cells=[]
   while todo:
    x,y=todo.pop(); cells.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<R and 0<=b<C and (a,b) not in seen and g[a][b]==col:
      seen.add((a,b)); todo.append((a,b))
   obs.append((col,cells))
 return obs

def settle(g, direction, barrier=2):
 R,C=len(g),len(g[0]); obs=components(g,barrier)
 changed=True
 while changed:
  changed=False
  occupied={p:i for i,(_,cells) in enumerate(obs) for p in cells}
  # process objects toward direction in leading-first order, but simultaneous one-cell update
  updates=[]
  for i,(col,cells) in enumerate(obs):
   dest=[(r+direction,c) for r,c in cells]
   if any(r<0 or r>=R or g[r][c]==barrier for r,c in dest): continue
   if any(p in occupied and occupied[p]!=i for p in dest): continue
   updates.append(i)
  for i in updates:
   col,cells=obs[i]; obs[i]=(col,[(r+direction,c) for r,c in cells]); changed=True
 out=[[0]*C for _ in range(R)]
 for r in range(R):
  for c in range(C):
   if g[r][c]==barrier: out[r][c]=barrier
 for col,cells in obs:
  for r,c in cells: out[r][c]=col
 return out,obs

